import sys

def process_data(data):
    if not data:
        sys.exit(1)
    try:
        # 仮の処理
        result = data.split()
        if len(result) < 2:
            raise ValueError("不十分なデータ")
        return result[0], result[1]
    except Exception as e:
        print(f"エラー: {e}")
        sys.exit(2)

if __name__ == "__main__":
    user_input = input("データを入力してください: ")
    process_data(user_input)

